                    "sql": "create or replace table maplemonk.rar_tally_gst_fact_items as (select cast(qty as int64) as quantity, cast(cess as float64) as cess, cast(cgst as float64) as cgst, cast(IGST as float64) as igst, cast(sgst as float64) as sgst, cast(parse_date(\'%d-%m-%Y\',Date) as date) as Date, cast(parse_date(\'%d-%m-%Y\',Original_Invoice_Date) as date) as Invoice_date, case when channel_invoice_created <> \'\' then cast(parse_date(\'%Y-%m-%d\',left(Channel_Invoice_Created,10)) as date) else null end as Channel_Invoice_Created, cast(sales as float64) as sales, cast(total as float64) as total, cast(UTGST as float64) as utgst, entity, godown, awb_num, currency, hsn_code, replace(cess_rate,\'Cess Rate\',\'\') as cess_rate, replace(IGST_Rate,\'IGST\',\'\') as igst_rate, replace(CGST_Rate,\'CGST\',\'\') as cgst_rate, replace(SGST_Rate,\'SGST\',\'\') as sgst_rate, replace(UTGST_Rate,\'UTGST\',\'\') as utgst_rate, cast(TCS_Amount as float64) as TCS_Amount, cast(unit_price as float64) as unit_price, upper(t.Product_Name) as product_name, cast(store_credit as float64) as store_credit, cast(Channel_entry as float64) as channel_entity, channel_ledger as channel, Invoice_number, payment_method, cast(Discount_Amount as float64) as discount, cast(conversion_rate as float64) as conversion_rate, original_sale_no, upper(Product_SKU_Code) as sku, sale_order_number, Billing_Party_Code, channel_party_gstin, shipping_address_city as city, Shipping_Address_State as state, Shipping_Address_Pincode as pincode, cast(Adjustment_In_Selling_Price as float64) as Adjustment_In_Selling_Price, url, pic.pic_no, pic.myntra_style_id from maplemonk.unicommerce_get_tally_gst_report t LEFT JOIN ( select * from (select product_name, category, size, mrp, cost as cogs, URL, SKU_Code, row_number()over (partition by SKU_Code order by length(ifnull(SKU_Code,\'\')) desc) rw from rainandrainbow-wh.maplemonk.RAR_SKU_MASTER ) where rw = 1 ) sk ON UPPER(sk.SKU_CODE) = upper(Product_SKU_Code) LEFT JOIN 